 for i,(slug,title,lead,desc,items,ico) in enumerate(OFFERINGS):
  services+=f'<article class="service-detail" id="{slug}"><div class="service-number">0{i+1}</div><div class="service-title">{icon(ico)}<h2>{title}</h2></div><div class="service-description"><h3>{lead}</h3><p>{desc}</p><ul>'+''.join(f'<li>{item}</li>' for item in items)+'</ul>'+textlink('Discuss this service',f'@ROOT@contact/index.html?interest={"assessment" if slug=="assessment" else "demo" if slug=="software" else "leadership" if slug=="leadership" else "modernization" if slug=="transformation" else slug}')+'</div></article>'
 services+='''</div></section><section class="section approach-section"><div class="container"><p class="eyebrow">Our approach</p><h2>From understanding<br>to implementation.</h2><div class="approach-grid"><article><span>01 / DISCOVER</span><h3>Start with the business.</h3><p>Understand your objectives, operational challenges, teams and technology landscape.</p></article><article><span>02 / ALIGN</span><h3>Define a practical path.</h3><p>Connect priorities to scope, architecture and a roadmap that fits your organization.</p></article><article><span>03 / DELIVER</span><h3>Work through the detail.</h3><p>Bring advisory and hands-on technical work together through implementation and change.</p></article></div></div></section>'''+cta()
 build_page('services',services)
 about=intro('About EclipseIQ Technologies Inc.','Insurance is our context.<br><span>Technology is our craft.</span>','A Canadian company combining executive leadership, insurance operations experience and hands-on technology expertise.')
