 contact=intro('Contact EclipseIQ','Your priorities.<br><span>Our next conversation.</span>','Discuss your technology landscape, an operational challenge, a leadership need or an EclipseSME demonstration.')+'''<section class="section"><div class="container contact-grid"><aside><p class="eyebrow">Let’s understand what you need</p><h2>Start with the business.<br>We’ll connect the technology.</h2><p>Tell us a little about your organization and what you’re working towards. A high-level overview is all we need to begin.</p><div class="contact-support"><div>'''+icon('compass')+'''<span>Insurance technology consulting</span></div><div>'''+icon('leadership')+'''<span>Fractional CIO / COO / CTO leadership</span></div><div>'''+icon('platform')+'''<span>EclipseSME & software solutions</span></div></div><p class="contact-location">Based in Canada.<br>Working with insurance organizations internationally.</p></aside><form id="inquiry-form" novalidate><p id="delivery-note" class="form-note">JavaScript is required for secure online inquiries. The form is not yet configured for live delivery.</p><noscript><p>Enable JavaScript to use the form. No inquiry has been sent.</p></noscript><div class="form-grid"><div><label for="name">Your name <span>(required)</span></label><input id="name" name="name" autocomplete="name" required maxlength="120"></div><div><label for="email">Email address <span>(required)</span></label><input id="email" name="email" type="email" autocomplete="email" required maxlength="254"></div><div><label for="company">Company name <span>(required)</span></label><input id="company" name="company" autocomplete="organization" required maxlength="160"></div><div><label for="company-type">Type of organization</label><select id="company-type" name="company_type"><option value="">Please select</option><option>Insurer</option><option>MGA / MGU</option><option>Reinsurer</option><option>Broker</option><option>Program administrator</option><option>Other</option></select></div></div><label for="interest">Primary area of interest <span>(required)</span></label><select id="interest" name="interest" required><option value="">Choose a topic</option><option value="consulting">Strategic consulting</option><option value="modernization">Digital transformation & integration</option><option value="leadership">Fractional CIO / COO / CTO leadership</option><option value="coaching">Team development & coaching</option><option value="assessment">Eclipse Totality Assessment™</option><option value="audit">Audit readiness</option><option value="security">Security review</option><option value="demo">EclipseSME demonstration / software</option><option value="other">Other / more than one service</option></select><fieldset><legend>Preferred contact method(s)</legend><p class="field-hint">Select any that apply. Email is selected by default.</p><div class="contact-options"><label><input type="checkbox" name="contact_method" value="Email" checked> Email</label><label><input type="checkbox" name="contact_method" value="Phone"> Phone call</label><label><input type="checkbox" name="contact_method" value="SMS"> SMS / text</label></div></fieldset><label for="phone">Phone number <span>(required for a call or text)</span></label><input id="phone" name="phone" type="tel" autocomplete="tel" maxlength="40"><label for="message">How can we help? <span>(required)</span></label><textarea id="message" name="message" rows="5" required minlength="10" maxlength="5000" aria-describedby="message-hint"></textarea><p class="field-hint" id="message-hint">Tell us about the services you need and your priorities. Do not include confidential, financial or policyholder information.</p><div class="honeypot" aria-hidden="true"><label for="website">Leave this field empty</label><input id="website" name="_gotcha" tabindex="-1" autocomplete="off"></div><div id="form-captcha"></div><p class="form-privacy">We use your information to respond to your inquiry. Read our <a href="@ROOT@privacy-policy/index.html">Cookies & privacy</a> information.</p><button class="button" type="submit" disabled>Send inquiry '''+ARROW+'''</button><p id="form-status" class="form-status" role="status" aria-live="polite" aria-atomic="true" tabindex="-1" hidden></p></form></div></section>'''
 build_page('contact',contact)
 privacy=intro('Cookies & privacy','Your information.<br><span>Your choices.</span>','How this website handles inquiries, browser storage and optional analytics.')+'''<section class="section"><div class="container legal"><p class="eyebrow">Website privacy notice / 23 October 2026</p><h2>Information we collect and use</h2><p>EclipseIQ Technologies Inc. uses the details you provide—such as your name, email address, company, phone number and message—to respond to inquiries, discuss demonstrations and service requests, and communicate about your requirements. Only share a high-level overview; do not include confidential or policyholder information.</p><p>We do not sell or rent your personal information. Information may be processed by service providers helping operate this website and respond to inquiries, or shared where required by law. Appropriate handling and security matter, but no internet transmission or storage method is completely secure.</p><h2>Contact form providers</h2><p>When live delivery is configured, inquiries are processed through Formspree. Optional Google reCAPTCHA may protect the form from spam if enabled. These services process information needed for delivery and verification. Review <a href="https://formspree.io/legal/privacy-policy/" target="_blank" rel="noopener noreferrer">Formspree’s privacy policy (new tab)</a> and, when enabled, <a href="https://policies.google.com/privacy" target="_blank" rel="noopener noreferrer">Google’s privacy policy (new tab)</a>.</p><p>Local previews identify simulated submissions clearly; they do not deliver inquiries. Hosted delivery remains unavailable until configured with EclipseIQ’s own endpoint.</p><h2 id="cookies">Cookies and browser storage</h2><p>This site stores your optional analytics preference in your browser for up to 180 days. This essential preference helps respect your choice. If storage is unavailable, your selection applies to the current page only.</p><p>Optional analytics remains off until you accept. The site is prepared for EclipseIQ’s Google Analytics 4 property, but no analytics runs without its configured Measurement ID. With consent, page-view data uses the canonical page address and page title. The implementation does not deliberately include form contents, query strings or URL fragments. Advertising features are disabled.</p><h2>Change or withdraw consent</h2><p>Use Cookie preferences in the footer to accept or reject optional analytics at any time. Rejecting after acceptance disables collection and reloads the page to unload the analytics code. Accessible first-party analytics cookies are removed where possible. The site cannot delete third-party or HttpOnly cookies or remove information already collected.</p><h2>Technical information and external sites</h2><p>The hosting provider may process IP addresses, browser information and access logs when serving this website. External sites have their own privacy practices. Links opening in a new tab are identified.</p><h2>Your privacy questions and requests</h2><p>You may ask about information you have shared, request access, correction or deletion, or ask to stop optional marketing communications. Use the <a href="@ROOT@contact/index.html">contact form</a> for an initial request without including sensitive details. EclipseIQ can follow up to verify and address it as appropriate.</p><h2>Updates to this notice</h2><p>This notice may be updated as website features and practices change. Please review it periodically. It replaces WordPress-specific cookie descriptions for this static website.</p></div></section>'''
 build_page('privacy',privacy)
 for alias in ['privacy/','cookie-policy-ca/','cookie-policy-ca-2/']:build_page('privacy',privacy,alias=alias)
